// GENERATED by scripts/build-io.mjs from src/ - edit the source, not this file.
// Wire frame -> UI message. Trimmed from faststore-agentic-base's
// agentSocketMessage.ts / agentHistory.ts: same typed-product reading, no
// VTEX/FastStore SKU-seller cart resolution (this widget has no storefront
// GraphQL to resolve against - product cards link out via `product_url`).
import { WireMessageBody, WireHistoryEntry, WireProductItem, MediaKind } from './wwcClient';

export interface ChatProduct {
  /** `product_retailer_id`: `sku`, `sku#seller` or `sku#seller#tradePolicy`. */
  key: string;
  name: string;
  price?: number;
  image?: string;
  url?: string;
  /** Used only when `key` carries no seller of its own. */
  sellerId?: string;
  /** Both optional on the wire; the detail sheet shows them only when sent. */
  description?: string;
  listPrice?: number;
}

export interface ChatMessage {
  id: string;
  direction: 'agent' | 'user';
  /** Epoch ms. Real send/receive time - the UI never invents one. */
  time?: number;
  text: string;
  mediaUrl?: string;
  /** How to play/show `mediaUrl`. Read from the wire, never guessed from the URL. */
  mediaKind?: MediaKind;
  /** File name for a `file` attachment: the local one when we sent it, else the URL's basename. */
  mediaName?: string;
  quickReplies?: string[];
  listItems?: Array<{ title: string; description?: string }>;
  products?: ChatProduct[];
  productsHeader?: string;
}

const MEDIA_KINDS: MediaKind[] = ['image', 'video', 'audio', 'file'];

function mediaKindOf(body: WireMessageBody): MediaKind | undefined {
  const kind = body.type as MediaKind | undefined;
  if (kind && MEDIA_KINDS.includes(kind)) return kind;
  // History entries and some channels omit the type but still carry a URL; a
  // generic file chip is the honest fallback, never a guess at the format.
  return body.media_url ? 'file' : undefined;
}

/** Last path segment of a URL, for labelling a file someone else sent. */
function basename(url: string | undefined): string | undefined {
  if (!url) return undefined;
  try {
    const path = new URL(url, window.location.origin).pathname;
    return decodeURIComponent(path.split('/').filter(Boolean).pop() || '') || undefined;
  } catch {
    return undefined;
  }
}

function parsePrice(value: string | undefined): number | undefined {
  if (!value) return undefined;
  const parsed = Number.parseFloat(String(value).replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : undefined;
}

function toProduct(item: WireProductItem, idx: number): ChatProduct | null {
  const retailerId = (item.product_retailer_id || item.retailer_id)?.trim();
  if (!retailerId && !item.name) return null;
  const price = parsePrice(item.sale_price) ?? parsePrice(item.price);
  const listPrice = parsePrice(item.price);
  return {
    key: retailerId || `${item.name}_${idx}`,
    name: item.name?.trim() || 'Produto',
    price,
    // Only a real discount: `price` is the list price and `sale_price` the one
    // being charged, so they are equal whenever there is no promo.
    listPrice: listPrice !== undefined && price !== undefined && listPrice > price ? listPrice : undefined,
    image: item.image?.trim() || undefined,
    url: item.product_url?.trim() || undefined,
    sellerId: item.seller_id?.trim() || undefined,
    description: item.description?.trim() || undefined,
  };
}

function typedProducts(body: WireMessageBody): { products: ChatProduct[]; header?: string } {
  const action = body.interactive?.action;
  const raw = [
    ...(action?.product_items ?? []),
    ...(action?.sections ?? []).flatMap((s) => s.product_items ?? []),
    ...(body.order?.product_items ?? []),
    // The shape the agents actually broadcast to web chat.
    ...(body.catalog_message?.products ?? []).flatMap((group) => group.product_retailer_info ?? []),
  ];
  const products = raw.map(toProduct).filter((p): p is ChatProduct => p !== null);
  return {
    products,
    header:
      body.interactive?.header?.text?.trim() ||
      action?.sections?.[0]?.title?.trim() ||
      body.catalog_message?.products?.[0]?.product?.trim() ||
      undefined,
  };
}

/**
 * The manager mirrors a finished catalog turn as `stream_end.content`: the
 * whole tool envelope (`is_final_output` + `messages_sent`), not a sentence.
 * That string is already on screen as the broadcast. Parsing it here keeps
 * the raw JSON out of the thread.
 */
export function expandFinalEnvelope(idBase: string, raw: string): ChatMessage[] | null {
  const trimmed = raw.trim();
  if (!trimmed.startsWith('{') || !trimmed.includes('"messages_sent"')) return null;
  let data: unknown;
  try {
    data = JSON.parse(trimmed);
  } catch {
    return null;
  }
  if (!data || typeof data !== 'object') return null;
  const sent = (data as { is_final_output?: boolean; messages_sent?: unknown }).messages_sent;
  if ((data as { is_final_output?: boolean }).is_final_output !== true || !Array.isArray(sent)) return null;
  return sent
    .map((item, index) => {
      const row = item as { text?: string; catalog_message?: WireMessageBody['catalog_message'] };
      return toChatMessage(`${idBase}_${index}`, 'agent', {
        text: row.text,
        catalog_message: row.catalog_message,
      });
    })
    .filter((message) => message.text.trim() || message.products?.length);
}

/** True once a streaming buffer is clearly the catalog envelope, not prose. */
export function isFinalEnvelopeStream(text: string): boolean {
  const trimmed = text.trimStart();
  return trimmed.startsWith('{') && (trimmed.includes('"is_final_output"') || trimmed.includes('"messages_sent"'));
}

function productKey(products?: ChatProduct[]): string {
  return (products ?? [])
    .map((product) => product.key)
    .sort()
    .join('|');
}

function sameProducts(a?: ChatProduct[], b?: ChatProduct[]): boolean {
  const left = productKey(a);
  const right = productKey(b);
  return Boolean(left) && left === right;
}

/** Drops an envelope turn the broadcast already painted. */
export function mergeAgentTurn(thread: ChatMessage[], incoming: ChatMessage): ChatMessage[] {
  const text = incoming.text.trim();
  const textAlready = Boolean(text) && thread.some((message) => message.direction === 'agent' && message.text.trim() === text);
  const productsAlready =
    Boolean(incoming.products?.length) &&
    thread.some((message) => message.direction === 'agent' && sameProducts(message.products, incoming.products));
  if (textAlready && (!incoming.products?.length || productsAlready)) return thread;
  if (!text && productsAlready) return thread;
  if (textAlready && incoming.products?.length) {
    const index = thread.findIndex((message) => message.direction === 'agent' && message.text.trim() === text && !message.products?.length);
    if (index >= 0) {
      const next = thread.slice();
      next[index] = { ...next[index], products: incoming.products, productsHeader: incoming.productsHeader ?? next[index].productsHeader };
      return next;
    }
  }
  return [...thread, incoming];
}

export function toChatMessage(
  id: string,
  direction: 'agent' | 'user',
  body: WireMessageBody | undefined,
  time: number = Date.now(),
): ChatMessage {
  if (!body) return { id, direction, time, text: '' };

  const text = (body.text ?? body.caption ?? '').trim();
  const { products, header } = typedProducts(body);
  // A catalog message often names the category in both the body and the group;
  // printing it twice, one under the other, just looks like a bug.
  const listHeader = header && header !== text ? header : undefined;

  return {
    id,
    direction,
    time,
    text,
    mediaUrl: body.media_url?.trim() || undefined,
    mediaKind: mediaKindOf(body),
    mediaName: body.media_url ? basename(body.media_url) : undefined,
    quickReplies: body.quick_replies?.length ? body.quick_replies : undefined,
    listItems: body.list_message?.list_items?.length
      ? body.list_message.list_items.map((it) => ({ title: it.title ?? '', description: it.description }))
      : undefined,
    products: products.length ? products : undefined,
    productsHeader: listHeader,
  };
}

/** History timestamps arrive in seconds on some channels and ms on others. */
function toEpochMs(ts: unknown): number | undefined {
  const n = Number(ts);
  if (!Number.isFinite(n) || n <= 0) return undefined;
  return n < 1e12 ? n * 1000 : n;
}

/**
 * History arrives NEWEST FIRST and `direction` is inverted relative to ours:
 * the server's "in" is the agent, "out" is the shopper. Both measured against
 * the live channel, not assumed - see docs/05-websocket-transport.md in
 * faststore-agentic-base for how this was found.
 */
export function historyToThread(entries: WireHistoryEntry[]): ChatMessage[] {
  const ordered = entries.slice().sort((a, b) => Number(a.timestamp ?? 0) - Number(b.timestamp ?? 0));
  return ordered.reduce<ChatMessage[]>((thread, entry, idx) => {
    const id = `hist_${idx}_${entry.timestamp}`;
    const time = toEpochMs(entry.timestamp);
    const direction = entry.direction === 'in' ? 'agent' : 'user';
    if (direction === 'user') return [...thread, toChatMessage(id, direction, entry.message, time)];
    const expanded = expandFinalEnvelope(id, entry.message?.text ?? '');
    const turns = (expanded ?? [toChatMessage(id, direction, entry.message, time)]).map((message) => ({ ...message, time }));
    return turns.reduce(mergeAgentTurn, thread);
  }, []);
}
